import type { CanvasElement, CanvasScene, NormalizedCrop } from './panel-visual.document';

type TextElement = Extract<CanvasElement, { type: 'text' }>;
export type TextMeasurer = (text: string, style: TextElement) => { width: number; supported: boolean };
export type CanvasDiagnostic = {
  elementId: string;
  code: 'OUTSIDE_ARTBOARD' | 'TEXT_OVERFLOW' | 'UNSUPPORTED_GLYPH';
  message: string;
};
export type CanvasLayout = {
  elements: { element: CanvasElement; lines?: { text: string; x: number; y: number }[] }[];
  diagnostics: CanvasDiagnostic[];
};

export function cropSourceRect(width: number, height: number, crop?: NormalizedCrop) {
  const rect = crop ?? { x: 0, y: 0, width: 1, height: 1 };
  return { x: rect.x * width, y: rect.y * height, width: rect.width * width, height: rect.height * height };
}

export function layoutCanvas(scene: CanvasScene, measure: TextMeasurer): CanvasLayout {
  const diagnostics: CanvasDiagnostic[] = [];
  const elements = scene.elements.map(element => {
    const box = element.type === 'line'
      ? { x: Math.min(element.x1, element.x2) - element.strokeWidth / 2, y: Math.min(element.y1, element.y2) - element.strokeWidth / 2, width: Math.abs(element.x2 - element.x1) + element.strokeWidth, height: Math.abs(element.y2 - element.y1) + element.strokeWidth }
      : element;
    if (box.x < 0 || box.y < 0 || box.x + box.width > scene.width || box.y + box.height > scene.height) {
      diagnostics.push({ elementId: element.id, code: 'OUTSIDE_ARTBOARD', message: 'Element extends outside the artboard.' });
    }
    if (element.type !== 'text') return { element };
    const metrics = measure(element.text, element);
    if (!metrics.supported) diagnostics.push({ elementId: element.id, code: 'UNSUPPORTED_GLYPH', message: 'Text contains characters not supported by the selected font.' });
    const wrapped: string[] = [];
    let tooWide = false;
    for (const paragraph of element.text.split('\n')) {
      let line = '';
      // Each input character is visited once; measurement is bounded by the document text limit.
      for (const character of paragraph) {
        const candidate = line + character;
        if (measure(candidate, element).width > element.width && line) {
          const breakAt = line.lastIndexOf(' ');
          if (breakAt > 0) {
            wrapped.push(line.slice(0, breakAt));
            line = line.slice(breakAt + 1) + character;
          } else {
            wrapped.push(line.trimEnd());
            line = character === ' ' ? '' : character;
          }
        } else line = candidate;
        if (measure(character, element).width > element.width) tooWide = true;
      }
      wrapped.push(line.trimEnd());
    }
    const lineHeight = element.fontSize * element.lineHeight;
    const neededHeight = wrapped.length * lineHeight;
    if (neededHeight > element.height || tooWide) {
      diagnostics.push({ elementId: element.id, code: 'TEXT_OVERFLOW', message: tooWide ? 'A character is wider than the text box.' : `Text needs ${neededHeight}px height; box has ${element.height}px.` });
    }
    const lines = wrapped.map((text, index) => {
      const width = measure(text, element).width;
      const offset = element.align === 'center' ? (element.width - width) / 2 : element.align === 'right' ? element.width - width : 0;
      return { text, x: element.x + offset, y: element.y + index * lineHeight };
    });
    return { element, lines };
  });
  return { elements, diagnostics };
}
